import request from './request'

/** 仪表盘总览 */
export function dashboard() {
  return request({
    url: '/admin/stats/dashboard',
    method: 'get',
  })
}

/** 热门岗位排行 */
export function jobRanking(params) {
  return request({
    url: '/admin/stats/job-ranking',
    method: 'get',
    params,
  })
}

/** 投递趋势 */
export function applyTrend(params) {
  return request({
    url: '/admin/stats/apply-trend',
    method: 'get',
    params,
  })
}
